INSERT INTO kegiatan
  (title, slug, category, summary, description, image_url, is_active, is_highlight, sort_order)
VALUES
  (
    'Gathering Asesor & Tasyakuran Kantor LSP FIT',
    'kegiatan-gathering-asesor-tasyakuran-kantor-lsp-fit',
    'Kegiatan Terbaru',
    'Momen kebersamaan pengurus, anggota, dan asesor dalam memperkuat silaturahmi sekaligus mensyukuri hadirnya ruang kerja sebagai pusat koordinasi kegiatan organisasi.',
    'Kegiatan Gathering Asesor & Tasyakuran Kantor LSP FIT menjadi salah satu momentum penting dalam perjalanan organisasi. Acara ini tidak hanya menjadi agenda seremonial, tetapi juga menjadi ruang temu bagi para pengurus, anggota, asesor, dan pihak-pihak yang selama ini berperan dalam mendukung pengembangan ekosistem fasilitator dan instruktur di Indonesia.\n\nMelalui kegiatan ini, seluruh peserta memiliki kesempatan untuk mempererat hubungan profesional dalam suasana yang lebih hangat dan akrab. Pertemuan seperti ini penting bagi organisasi berbasis asosiasi karena kolaborasi yang kuat tidak hanya dibangun melalui program formal, tetapi juga melalui komunikasi, kepercayaan, dan rasa memiliki terhadap tujuan bersama.\n\nTasyakuran kantor menjadi simbol rasa syukur atas hadirnya ruang kerja yang dapat mendukung aktivitas koordinasi, administrasi, diskusi program, serta pengembangan layanan organisasi. Kantor bukan sekadar tempat operasional, melainkan pusat aktivitas yang mempertemukan gagasan, pengalaman, dan rencana strategis untuk memperkuat kontribusi organisasi bagi para anggotanya.\n\nDalam suasana gathering, para peserta dapat saling bertukar pengalaman mengenai praktik fasilitasi, pelatihan, asesmen, dan pengembangan kompetensi. Interaksi tersebut menjadi bekal penting untuk menjaga kualitas layanan, memperluas perspektif, dan memastikan setiap kegiatan organisasi tetap relevan dengan kebutuhan dunia kerja, pendidikan, dan pengembangan sumber daya manusia.',
    '/assets/gallery/gathering-asesor-%26-tasyakuran-kantor-lsp-fit-1.jpeg',
    1,
    1,
    60
  ),
  (
    'Penyelenggara Uji BBPVP Bandung',
    'kegiatan-penyelenggara-uji-bbpvp-bandung',
    'Asesmen',
    'Dokumentasi kegiatan penyelenggaraan uji kompetensi di BBPVP Bandung sebagai bagian dari dukungan terhadap peningkatan kualitas pelatihan.',
    'Kegiatan Penyelenggara Uji BBPVP Bandung menjadi salah satu dokumentasi penting dalam perjalanan penguatan kompetensi dan pelaksanaan asesmen yang terstruktur. Aktivitas ini memperlihatkan bagaimana proses uji kompetensi membutuhkan koordinasi yang matang antara penyelenggara, peserta, asesor, dan pihak pendukung agar setiap tahapan dapat berjalan tertib.\n\nDalam kegiatan ini, suasana profesional dibangun melalui kesiapan administrasi, pengaturan ruang, kelengkapan dokumen, dan pendampingan terhadap peserta. Setiap unsur tersebut menjadi bagian penting untuk memastikan pelaksanaan asesmen tidak hanya berlangsung formal, tetapi juga memberi pengalaman yang jelas bagi peserta yang mengikuti proses uji.\n\nAFIN melihat kegiatan seperti ini sebagai ruang pembelajaran bersama. Melalui dokumentasi dan keterlibatan berbagai pihak, organisasi dapat terus memperkuat pemahaman tentang praktik penyelenggaraan uji yang efektif, transparan, dan relevan dengan kebutuhan dunia pelatihan.\n\nKegiatan ini juga menegaskan pentingnya jejaring kelembagaan. Kolaborasi dengan balai pelatihan dan para praktisi menjadi modal utama dalam memperluas dampak program pengembangan kompetensi, khususnya bagi instruktur dan fasilitator yang bekerja di berbagai lingkungan pembelajaran.',
    '/assets/gallery/Penyelenggara-Uji-untuk-BBPVP-Bandung.jpeg',
    1,
    1,
    50
  ),
  (
    'Shopee Affiliate Program',
    'kegiatan-shopee-affiliate-program',
    'Pelatihan',
    'Kegiatan pengembangan kapasitas yang menghubungkan keterampilan fasilitasi dengan kebutuhan industri digital dan pemasaran berbasis konten.',
    'Shopee Affiliate Program menjadi salah satu kegiatan yang menunjukkan pentingnya adaptasi fasilitator dan instruktur terhadap perkembangan ekosistem digital. Program ini menghadirkan ruang belajar yang dekat dengan kebutuhan saat ini, terutama ketika pemasaran, komunikasi, dan pengembangan audiens semakin banyak berlangsung melalui kanal digital.\n\nDalam kegiatan ini, peserta tidak hanya mendapatkan pemahaman konseptual, tetapi juga didorong untuk melihat praktik secara lebih aplikatif. Materi yang dibahas membantu peserta memahami cara membangun pesan, mengelola konten, mengenali perilaku audiens, dan memanfaatkan platform digital sebagai sarana pengembangan aktivitas profesional.\n\nBagi AFIN, kegiatan seperti ini menjadi contoh bagaimana asosiasi dapat menghadirkan program yang responsif terhadap perubahan zaman. Fasilitator dan instruktur perlu terus memperluas kapasitasnya agar mampu mendampingi pembelajaran yang relevan, termasuk pada topik-topik yang bersinggungan dengan ekonomi digital.\n\nSuasana kolaboratif dalam kegiatan ini juga membuka ruang diskusi antar peserta. Setiap peserta memiliki pengalaman, tantangan, dan pendekatan yang berbeda dalam memanfaatkan kanal digital. Pertukaran pengalaman tersebut menjadi nilai tambah karena pembelajaran tidak hanya datang dari narasumber, tetapi juga dari praktik peserta lainnya.',
    '/assets/gallery/ToT-shopee-affiliate-2.jpeg',
    1,
    1,
    40
  ),
  (
    'Penguatan Kompetensi Instruktur BBPV Semarang',
    'kegiatan-penguatan-kompetensi-instruktur-bbpv-semarang',
    'Kompetensi',
    'Kegiatan pengembangan kapasitas instruktur pemerintah untuk memperkuat kualitas pembelajaran, fasilitasi, dan pendampingan peserta pelatihan.',
    'Penguatan Kompetensi Instruktur BBPV Semarang merupakan kegiatan yang berfokus pada peningkatan kualitas instruktur dalam menjalankan peran pembelajaran. Di tengah perubahan kebutuhan dunia kerja, instruktur dituntut tidak hanya menguasai materi, tetapi juga mampu menyampaikan pembelajaran secara efektif, kontekstual, dan mudah diterapkan oleh peserta.\n\nKegiatan ini menjadi ruang untuk memperbarui cara pandang terhadap proses pelatihan. Para peserta dapat mengkaji kembali pendekatan fasilitasi, penyusunan alur pembelajaran, teknik komunikasi, serta cara membangun interaksi yang produktif di dalam kelas. Hal-hal tersebut menjadi bagian penting dalam menciptakan pengalaman belajar yang bermakna.\n\nAFIN memandang penguatan instruktur sebagai agenda strategis. Instruktur memiliki peran langsung dalam membentuk kompetensi peserta pelatihan, sehingga kualitas instruktur akan berdampak pada kualitas lulusan program. Karena itu, kegiatan seperti ini perlu terus didorong sebagai bagian dari pengembangan profesi yang berkelanjutan.',
    '/assets/gallery/penguatan-kompetensi-instruktur-pemerintah-BBPV-semarang.jpeg',
    1,
    0,
    30
  ),
  (
    'Penguatan Kompetensi Instruktur BBPVP Bandung',
    'kegiatan-penguatan-kompetensi-instruktur-bbpvp-bandung',
    'Kompetensi',
    'Ruang pengembangan instruktur untuk memperkuat kualitas fasilitasi, desain pembelajaran, dan kesiapan menghadapi kebutuhan pelatihan modern.',
    'Penguatan Kompetensi Instruktur BBPVP Bandung menjadi kegiatan yang menekankan pentingnya peningkatan kapasitas instruktur secara berkelanjutan. Instruktur memiliki posisi strategis sebagai penghubung antara standar kompetensi, kebutuhan industri, dan proses pembelajaran yang dialami peserta.\n\nDalam kegiatan ini, peserta diajak untuk melihat kembali peran instruktur secara lebih luas. Seorang instruktur bukan hanya penyampai materi, melainkan perancang pengalaman belajar, fasilitator diskusi, pendamping praktik, dan pengarah proses refleksi peserta. Peran tersebut membutuhkan keterampilan teknis sekaligus kemampuan komunikasi yang matang.\n\nAFIN mendukung kegiatan seperti ini karena sejalan dengan misi memperkuat jejaring fasilitator dan instruktur di Indonesia. Melalui ruang pertemuan profesional, anggota dan mitra dapat saling berbagi perspektif, memperbarui metode, serta menyusun pendekatan yang lebih relevan dengan kebutuhan peserta pelatihan.',
    '/assets/gallery/penguatan-kompetensi-instruktur-pemerintah-BBPVP-Bandung.jpeg',
    1,
    0,
    20
  ),
  (
    'Sertifikasi Kompetensi Balai Jasa Konstruksi Wilayah III Jakarta',
    'kegiatan-sertifikasi-kompetensi-balai-jasa-konstruksi-wilayah-iii-jakarta',
    'Sertifikasi',
    'Dokumentasi kegiatan sertifikasi kompetensi yang mendukung penguatan kualitas sumber daya manusia di sektor jasa konstruksi.',
    'Kegiatan Sertifikasi Kompetensi Balai Jasa Konstruksi Wilayah III Jakarta menjadi bagian dari upaya memperkuat kualitas tenaga kerja dan pelaksana pelatihan di sektor jasa konstruksi. Sektor ini membutuhkan sumber daya manusia yang tidak hanya memahami teori, tetapi juga mampu menunjukkan kompetensi kerja sesuai standar yang berlaku.\n\nPelaksanaan kegiatan sertifikasi memberikan ruang bagi peserta untuk menunjukkan kemampuan, pengalaman, dan pemahaman mereka melalui proses yang terstruktur. Setiap tahapan membutuhkan kesiapan dokumen, pemahaman terhadap skema, serta komunikasi yang baik antara peserta dan tim pelaksana.\n\nAFIN memandang kegiatan ini sebagai contoh penting kolaborasi lintas sektor. Ketika asosiasi, lembaga pelatihan, dan institusi terkait bekerja bersama, proses pengembangan kompetensi dapat berjalan lebih efektif dan memberikan kontribusi nyata bagi peningkatan kualitas profesi.',
    '/assets/gallery/kegiatan-sertifikasi-kompetensi-Balai-Jasa-Konstruksi-Wilayah-III-Jakarta.jpeg',
    1,
    0,
    10
  )
